export type ExportKind = (typeof EXPORTS)[number]['kind']
export type ExportResult = { name: string; text: string } | { error: string }

const SYM_NAMES: Record<string, string> = {
  '+': 'PLUS', '-': 'MINUS', '*': 'MUL', '/': 'DIV', '%': 'MOD', '(': 'LPAREN', ')': 'RPAREN',
  '[': 'LBRACKET', ']': 'RBRACKET', '{': 'LBRACE', '}': 'RBRACE', ',': 'COMMA', ';': 'SEMICOLON',
  ':': 'COLON', '.': 'DOT', '=': 'ASSIGN', '==': 'EQ', '!=': 'NEQ', '<': 'LT', '<=': 'LE', '>': 'GT',
  '>=': 'GE', '!': 'NOT', '&&': 'AND', '||': 'OR', $: 'EOF', '?': 'QUESTION', '=>': 'ARROW',
  '->': 'ARROW', '&': 'AMP', '|': 'PIPE', '^': 'CARET', '~': 'TILDE', '#': 'HASH', '@': 'AT',
}

const GEN_HEADER = 'Generated by tools/table-maker'

function nameMap(text: string) {
  const m = new Map<string, string>()
  text.split('\n').forEach((ln) => {
    const t = symbolList(ln)
    if (t.length >= 2) m.set(t[0], t[1])
  })
  return m
}

// Returns unique C identifiers for the given symbols.
function cNames(symbols: string[], prefix: string, mapText: string) {
  const map = nameMap(mapText)
  const used = new Set<string>()
  return symbols.map((sym) => {
    let name = map.get(sym)
    if (!name) {
      let base =
        SYM_NAMES[sym] ??
        sym
          .replace(/^<(.+)>$/, '$1')
          .replace(/'/g, '_PRIME')
          .replace(/[^A-Za-z0-9]+/g, '_')
          .replace(/^_+|_+$/g, '')
          .toUpperCase()
      if (!base) base = 'SYM'
      name = prefix + (/^[0-9]/.test(base) ? '_' + base : base)
    }
    let unique = name
    for (let i = 2; used.has(unique); i++) unique = `${name}_${i}`
    used.add(unique)
    return unique
  })
}

const cComment = (s: string) => s.replace(/\*\//g, '* /')
const mdCell = (s: string | number) => String(s).replace(/\|/g, '\\|')
const csvCell = (s: string) => (/[",\n;]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s)
const TEX: Record<string, string> = {
  '\\': '\\textbackslash{}', '{': '\\{', '}': '\\}', $: '\\$', '&': '\\&', '#': '\\#', '%': '\\%', _: '\\_',
  '^': '\\textasciicircum{}', '~': '\\textasciitilde{}', '<': '\\textless{}', '>': '\\textgreater{}', '|': '\\textbar{}',
}
const texEsc = (s: string) => s.replace(/[\\{}$&#%_^~<>|]/g, (c) => TEX[c])

function mdTable(header: string[], rows: (string | number)[][]) {
  return (
    [
      `| ${header.map(mdCell).join(' | ')} |`,
      `|${header.map(() => ' :-: ').join('|')}|`,
      ...rows.map((r) => `| ${r.map(mdCell).join(' | ')} |`),
    ].join('\n') + '\n'
  )
}

const csvTable = (rows: string[][]) => rows.map((r) => r.map(csvCell).join(',')).join('\n') + '\n'

function texTable(header: string[], rows: string[][]) {
  const spec = '|' + header.map(() => 'c').join('|') + '|'
  const line = (r: string[], mathRel: boolean) =>
    r.map((c, i) => (i > 0 && mathRel && /^[<=>]$/.test(c) ? `$${c}$` : texEsc(c))).join(' & ') + ' \\\\ \\hline'
  return [`% ${GEN_HEADER}`, `\\begin{tabular}{${spec}}`, '\\hline', line(header, false), ...rows.map((r) => line(r, true)), '\\end{tabular}', ''].join('\n')
}

const llGrid = (a: LLAnalysis) => a.N.map((A) => [A, ...a.cols.map((c) => (a.table.get(A)!.get(c) ?? []).join(', '))])

const precGrid = (prec: ProjectData['prec']) => {
  const cols = precCols(prec.terminals)
  return cols.map((r) => [r, ...cols.map((c) => getRel(prec.cells, r, c))])
}

