export const isImageExport = (kind: ExportKind) => kind.endsWith('-png')

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
// Changes: Takes the analysed grammar from the grammar module (N, T, S and the LL analysis) instead of deciding them again.
export function buildTableImage(kind: ExportKind, data: ProjectData, grammar: Grammar): { name: string; table: PngTable } | { error: string } {
  const a = grammar.ll
  if (kind === 'll-png') {
    if (!a) return { error: 'LL gramatika je prázdna.' }
    return { name: 'll-table.png', table: { title: 'LL tabuľka', header: ['', ...a.cols], rows: llGrid(a) } }
  }
  if (!data.prec.terminals.length) return { error: 'Precedenčná tabuľka je prázdna.' }
  return { name: 'prec-table.png', table: { title: 'Precedenčná tabuľka', header: ['', ...precCols(data.prec.terminals)], rows: precGrid(data.prec) } }
}

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "in the export tab could you add a simple preview when the latex version is selecter for export"
// Changes: Structured data for an HTML preview of the LaTeX exports (same content as the .tex output).
export type TexPreview =
  | { type: 'table'; header: string[]; rows: string[][] }
  | { type: 'def'; N: string[]; T: string[]; S: string; rules: { lhs: string; rhs: string[] }[] }

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
// Changes: Takes the analysed grammar from the grammar module (N, T, S and the LL analysis) instead of deciding them again.
export function buildTexPreview(kind: ExportKind, data: ProjectData, grammar: Grammar): TexPreview | null {
  const a = grammar.ll
  if (kind === 'def-tex') {
    const g = grammar
    if (!g.rules.length && !g.N.length && !g.T.length) return null
    return { type: 'def', N: g.N, T: g.T, S: g.S, rules: g.rules }
  }
  if (kind === 'll-tex') return a ? { type: 'table', header: ['', ...a.cols], rows: llGrid(a) } : null
  if (kind === 'prec-tex') {
    if (!data.prec.terminals.length) return null
    return { type: 'table', header: ['', ...precCols(data.prec.terminals)], rows: precGrid(data.prec) }
  }
  return null
}

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
// Changes: Takes the analysed grammar from the grammar module (N, T, S and the LL analysis) instead of deciding them again.
export function buildExport(kind: ExportKind, data: ProjectData, grammar: Grammar): ExportResult {
  const a = grammar.ll
  const { names, prec } = data
  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "could you add a tab where i will be able to define properties"
  // Changes: G = (N, T, P, S) as Markdown (with a symbol table) or as LaTeX.
  if (kind.startsWith('def')) {
    const g = grammar
    if (!g.rules.length && !g.N.length && !g.T.length) return { error: 'Definícia gramatiky je prázdna.' }
    if (kind === 'def-md') {
      const code = (s: string) => `\`${s}\``
      const set = (xs: string[]) => (xs.length ? `{ ${xs.map(code).join(', ')} }` : '∅')
      let md = `## Gramatika G = (N, T, P, S)\n\n- N = ${set(g.N)}\n- T = ${set(g.T)}\n- S = ${g.S ? code(g.S) : '–'}\n`
      md += `\n### P\n\n${g.rules.map((r, i) => `${i + 1}. ${code(ruleText(r))}`).join('\n') || '∅'}\n`
      const rows = [...g.N.map((s) => [s, 'N']), ...g.T.map((s) => [s, 'T'])].map(([s, k]) => [code(s), k, g.notes.get(s) ?? ''])
      if (rows.some((r) => r[2])) md += `\n### Symboly\n\n${mdTable(['Symbol', 'Druh', 'Popis'], rows)}`
      return { name: 'grammar.md', text: md }
    }
    const tt = (s: string) => `\\texttt{${texEsc(s)}}`
    const set = (xs: string[]) => (xs.length ? `\\{ ${xs.map(tt).join(', ')} \\}` : '\\emptyset')
    const rhs = (xs: string[]) => (xs.length ? xs.map(tt).join('\\,') : '\\varepsilon')
    const tex = [
      `% ${GEN_HEADER}`,
      '\\begin{align*}',
      'G &= (N, T, P, S) \\\\',
      `N &= ${set(g.N)} \\\\`,
      `T &= ${set(g.T)} \\\\`,
      `S &= ${g.S ? tt(g.S) : '-'}`,
      '\\end{align*}',
      ...(g.rules.length
        ? ['\\begin{enumerate}', ...g.rules.map((r) => `  \\item $${tt(r.lhs)} \\rightarrow ${rhs(r.rhs)}$`), '\\end{enumerate}']
        : []),
      '',
    ]
    return { name: 'grammar.tex', text: tex.join('\n') }
  }
  if (kind.startsWith('ll')) {
    if (!a) return { error: 'LL gramatika je prázdna.' }
    switch (kind) {
      case 'll-md': {
        const rules = a.rules.map((r, i) => `${i + 1}. \`${ruleText(r)}\``).join('\n')
        return { name: 'll-table.md', text: `## LL tabuľka\n\n${mdTable(['', ...a.cols], llGrid(a))}\n### Pravidlá\n\n${rules}\n` }
      }
      case 'll-sets-md': {
        const sets = mdTable(
          ['Neterminál', 'Empty', 'First', 'Follow'],
          a.N.map((n) => [n, a.empty.has(n) ? '{ ε }' : '∅', fmtSet(a.order(a.first.get(n)!)), fmtSet(a.order(a.follow.get(n)!))]),
        )
        const pred = mdTable(['#', 'Pravidlo', 'Predict'], a.rules.map((r, i) => [i + 1, ruleText(r), fmtSet(a.order(a.predict[i]))]))
        return { name: 'll-sets.md', text: `## Empty, First, Follow\n\n${sets}\n## Predict\n\n${pred}` }
      }
      case 'll-csv':
        return { name: 'll-table.csv', text: csvTable([['', ...a.cols], ...llGrid(a)]) }
      case 'll-tex':
        return { name: 'll-table.tex', text: texTable(['', ...a.cols], llGrid(a)) }
      case 'll-c': {
        const nt = cNames(a.N, names.ntPrefix, names.map)
        const t = cNames(a.cols, names.tPrefix, names.map)
        const ntCount = names.ntPrefix + 'COUNT'
        const tCount = names.tPrefix + 'COUNT'
        let c = `/* ${GEN_HEADER} */\n\n/* Rules:\n`
        a.rules.forEach((r, i) => {
          c += ` * ${String(i + 1).padStart(3)}: ${cComment(ruleText(r))}\n`
        })
        c += ' */\n\n'
        c += `typedef enum {\n${nt.map((n, i) => `    ${n}, /* ${cComment(a.N[i])} */`).join('\n')}\n    ${ntCount}\n} ll_nonterminal_t;\n\n`
        c += `typedef enum {\n${t.map((n, i) => `    ${n}, /* ${cComment(a.cols[i])} */`).join('\n')}\n    ${tCount}\n} ll_terminal_t;\n\n`
        c += `/* Rule number (1-based), 0 = syntax error */\nstatic const int LL_TABLE[${ntCount}][${tCount}] = {\n`
        a.N.forEach((A, i) => {
          const entries: string[] = []
          a.cols.forEach((col, j) => {
            const cell = a.table.get(A)!.get(col)
            if (cell) entries.push(`[${t[j]}] = ${cell[0]}${cell.length > 1 ? ` /* CONFLICT: ${cell.join(', ')} */` : ''}`)
          })
          c += `    [${nt[i]}] = { ${entries.join(', ')} },\n`
        })
        return { name: 'll_table.h', text: c + '};\n' }
      }
    }
  }

  if (!prec.terminals.length) return { error: 'Precedenčná tabuľka je prázdna.' }
  const cols = precCols(prec.terminals)
  switch (kind) {
    case 'prec-md':
      return { name: 'prec-table.md', text: `## Precedenčná tabuľka\n\n${mdTable(['', ...cols], precGrid(prec))}` }
    case 'prec-csv':
      return { name: 'prec-table.csv', text: csvTable([['', ...cols], ...precGrid(prec)]) }
    case 'prec-tex':
      return { name: 'prec-table.tex', text: texTable(['', ...cols], precGrid(prec)) }
    case 'prec-c': {
      const cn = cNames(cols, names.precPrefix, names.map)
      const count = names.precPrefix + 'COUNT'
      const rel = { '<': 'PREC_LT', '=': 'PREC_EQ', '>': 'PREC_GT' } as const
      let c = `/* ${GEN_HEADER} */\n\n`
      c += 'typedef enum {\n    PREC_NONE = 0, /* empty cell = syntax error */\n    PREC_LT,\n    PREC_EQ,\n    PREC_GT\n} prec_rel_t;\n\n'
      c += `typedef enum {\n${cn.map((n, i) => `    ${n}, /* ${cComment(cols[i])} */`).join('\n')}\n    ${count}\n} prec_terminal_t;\n\n`
      c += `/* [terminal on stack][input token] */\nstatic const prec_rel_t PREC_TABLE[${count}][${count}] = {\n`
      cols.forEach((r, i) => {
        const entries: string[] = []
        cols.forEach((col, j) => {
          const v = getRel(prec.cells, r, col)
          if (v) entries.push(`[${cn[j]}] = ${rel[v]}`)
        })
        c += `    [${cn[i]}] = { ${entries.join(', ')} },\n`
      })
      return { name: 'prec_table.h', text: c + '};\n' }
    }
  }
  return { error: 'Neznámy formát' }
}

export function downloadText(name: string, text: string, type = 'text/plain;charset=utf-8') {
  const url = URL.createObjectURL(new Blob([text], { type }))
  const link = document.createElement('a')
  link.href = url
  link.download = name
  document.body.appendChild(link)
  link.click()
  link.remove()
  setTimeout(() => URL.revokeObjectURL(url), 1000)
}

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "could you add a option to export the tables as PNG"
// Changes: Download a Blob (PNG) under the given file name.
export function downloadBlob(name: string, blob: Blob) {
  const url = URL.createObjectURL(blob)
  const link = document.createElement('a')
  link.href = url
  link.download = name
  document.body.appendChild(link)
  link.click()
  link.remove()
  setTimeout(() => URL.revokeObjectURL(url), 1000)
}

